214→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
215→func extractFirstPromptFromTranscript(data []byte) string {
216→	lines, err := transcript.ParseFromBytes(data)
217→	if err != nil {
218→		return ""
219→	}
220→	for _, line := range lines {
221→		if line.Type == "user" {
222→			prompt := extractTextFromMessage(line.Message)
223→			if prompt != "" {
224→				return prompt
225→			}
226→		}
227→	}
228→	return ""
229→}
230→
231→// extractTextFromMessage extracts the text content from a transcript message.
232→func extractTextFromMessage(msg json.RawMessage) string {
233→	// Try string content first (simple user messages)
234→	var simple struct {
235→		Content string `json:"content"`
236→	}
237→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
238→		return simple.Content
239→	}
240→
241→	// Try array content (messages with tool results, text blocks, etc.)
242→	var array struct {
243→		Content []struct {
244→			Type string `json:"type"`
245→			Text string `json:"text"`
246→		} `json:"content"`
247→	}
248→	if err := json.Unmarshal(msg, &array); err == nil {
249→		for _, block := range array.Content {
250→			if block.Type == "text" && block.Text != "" {
251→				return block.Text
252→			}
253→		}
254→	}
255→
256→	return ""
257→}
258→
259→// parseTranscriptBytes parses raw JSONL transcript data into transcript lines.
260→func parseTranscriptBytes(data []byte) ([]transcriptLine, error) {
261→	var lines []transcriptLine
262→	for _, lineData := range bytes.Split(data, []byte("\n")) {
263→		if len(lineData) == 0 {
264→			continue
265→		}
266→		var line transcriptLine
267→		if err := json.Unmarshal(lineData, &line); err != nil {
268→			continue // skip malformed lines
269→		}
270→		lines = append(lines, line)
271→	}
272→	return lines, nil
273→}
